const ZGEO = Object.create(SGEO, Object.getOwnPropertyDescriptors({
  // its own caches: anything left to the prototype would be Silverstone's
  ready:false, sc:1, _raw:null, _ef:null,
  get DATA(){ return ZAND_DATA; },
  LM:["", "pitbuilding", "mainstand"],
  pathRaw(){
    if(this._raw) return this._raw;
    const p = this.dec(this.DATA.path), raw = []; let x = 0, y = 0;
    for(let i = 0; i < p.length; i += 2){ x += p[i]; y += p[i + 1]; raw.push([x / 10, y / 10]); }
    // the mapped ways meet at slight angles, and at Tarzan and Turn 13 that reads as a kink
    // tighter than any real corner: cut the line into 3 m steps and ease it, all the way round
    let out = [];
    for(let i = 0; i < raw.length; i++){ const a = raw[i], b = raw[(i + 1) % raw.length];
      const k = Math.max(1, Math.ceil(Math.hypot(b[0] - a[0], b[1] - a[1]) / 3));
      for(let j = 0; j < k; j++) out.push([a[0] + (b[0] - a[0]) * j / k, a[1] + (b[1] - a[1]) * j / k]); }
    const m = out.length;
    for(let pass = 0; pass < 24; pass++){
      const c = out.map(q => q.slice());
      for(let i = 0; i < m; i++){ const a = c[(i - 1 + m) % m], b = c[(i + 1) % m];
        out[i][0] += 0.5 * ((a[0] + b[0]) / 2 - c[i][0]); out[i][1] += 0.5 * ((a[1] + b[1]) / 2 - c[i][1]); }
    }
    return (this._raw = out);
  },
  elev(u){ if(!this._ef) this._ef = elevMC(this.DATA.elev); return this._ef(u); },
  init(sc){
    if(this.ready && this.sc === sc) return this;
    SGEO.init.call(this, sc);
    this.coast = this.rings(this.DATA.coast, this.DATA.q)[0];
    this.seaZ = this.DATA.seaZ;
    return this;
  },
  // where on the real map a point of the squeezed world came from
  unwarp(x, y){
    const W = this.DATA.warp, s = x * W.ns[0] + y * W.ns[1] - W.s0;
    if(s <= 0) return [x, y];
    const t = x * W.dc[0] + y * W.dc[1];
    let tp = 1;
    if(t < W.t0 || t > W.t1){ const d = t < W.t0 ? W.t0 - t : t - W.t1; const q = Math.max(0, 1 - d / W.taper); tp = q * q * (3 - 2 * q); }
    const fe = 1 - (1 - W.F) * tp;
    const k = clamp((t - W.ts0) / 50, 0, W.sb.length - 1.001), i = Math.floor(k), f = k - i;
    const sb = Math.max(1, W.sb[i] + (W.sb[i + 1] - W.sb[i]) * f);
    const s1 = s < sb * fe ? s / fe : s + sb * (1 - fe), d = s1 - s;
    return [x + W.ns[0] * d, y + W.ns[1] * d];
  },
  // across the coast: how far out toward the sea this point is (0 is 60 m off the track's west side)
  across(x, y){ const W = this.DATA.warp; return x / this.sc * W.ns[0] + y / this.sc * W.ns[1] - W.s0; },   // 0 is 20 m off the track's west side
  dem(x, y){
    const s = this.sc, [rx, ry] = this.unwarp(x / s, y / s);
    return SGEO.dem.call(this, rx * s, ry * s);
  },
}));

